package main

import (
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/charmbracelet/bubbles/list"
	"github.com/charmbracelet/bubbletea"
	"github.com/charmbracelet/lipgloss"
)

const version = "v1.13.0"

type Config struct {
	Icons       bool
	DirOnly     bool
	HideHidden  bool
	Preview     bool
	WithBorder  bool
	Fuzzy       bool
	StartPath   string
}

type Model struct {
	config    Config
	path      string
	entries   []fs.DirEntry
	cursor    int
	quitting  bool
	exitPath  string
	exitCode  int
}

func main() {
	config := parseArgs()

	startPath := config.StartPath
	if startPath == "" {
		var err error
		startPath, err = os.Getwd()
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
	}

	// Try to open TTY
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		fmt.Fprintf(os.Stderr, "panic: could not open a new TTY: %v\n", err)
		os.Exit(2)
	}
	tty.Close()

	model := &Model{
		config:   config,
		path:     startPath,
		cursor:   0,
		exitCode: 1,
	}

	if err := model.loadEntries(); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}

	// Run the TUI
	p := bubbletea.NewProgram(model)
	finalModel, err := p.Run()
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}

	m := finalModel.(*Model)
	if m.exitPath != "" {
		fmt.Println(m.exitPath)
	}
	os.Exit(m.exitCode)
}

func parseArgs() Config {
	config := Config{
		StartPath: ".",
	}

	args := os.Args[1:]
	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "-h", "--help":
			printHelp()
			os.Exit(0)
		case "--version":
			fmt.Println(version)
			os.Exit(0)
		case "--icons":
			config.Icons = true
		case "--dir-only":
			config.DirOnly = true
		case "--hide-hidden":
			config.HideHidden = true
		case "--preview":
			config.Preview = true
		case "--with-border":
			config.WithBorder = true
		case "--fuzzy":
			config.Fuzzy = true
		default:
			if !strings.HasPrefix(args[i], "-") {
				config.StartPath = args[i]
			}
		}
	}

	return config
}

func printHelp() {
	fmt.Printf(`
  walk %s

  Usage: walk [path]

    arrows, hjkl  Move cursor
    enter         Enter directory
    backspace     Exit directory
    space         Toggle preview
    esc, q        Exit with cd
    ctrl+c        Exit without cd
    /             Fuzzy search
    d, delete     Delete file or dir
    y             Copy to clipboard
    .             Hide hidden files
    ?             Show help

  Flags:

    --icons        display icons
    --dir-only     show dirs only
    --hide-hidden  hide hidden files
    --preview      display preview
    --with-border  preview with border
    --fuzzy        fuzzy mode

`, strings.TrimPrefix(version, "v"))
}

func (m *Model) loadEntries() error {
	entries, err := os.ReadDir(m.path)
	if err != nil {
		return err
	}

	// Filter entries
	filtered := []fs.DirEntry{}
	for _, e := range entries {
		if m.config.HideHidden && strings.HasPrefix(e.Name(), ".") {
			continue
		}
		if m.config.DirOnly && !e.IsDir() {
			continue
		}
		filtered = append(filtered, e)
	}

	// Sort entries
	sort.Slice(filtered, func(i, j int) bool {
		// Directories first
		iIsDir := filtered[i].IsDir()
		jIsDir := filtered[j].IsDir()
		if iIsDir != jIsDir {
			return iIsDir
		}
		return filtered[i].Name() < filtered[j].Name()
	})

	m.entries = filtered
	if m.cursor >= len(m.entries) {
		m.cursor = len(m.entries) - 1
	}
	if m.cursor < 0 {
		m.cursor = 0
	}

	return nil
}

func (m Model) Init() bubbletea.Cmd {
	return nil
}

func (m Model) Update(msg bubbletea.Msg) (bubbletea.Model, bubbletea.Cmd) {
	switch msg := msg.(type) {
	case bubbletea.KeyMsg:
		switch msg.String() {
		case "q", "esc":
			if len(m.entries) > 0 {
				current := m.entries[m.cursor]
				if current.IsDir() {
					m.exitPath = filepath.Join(m.path, current.Name())
				} else {
					m.exitPath = m.path
				}
			} else {
				m.exitPath = m.path
			}
			m.exitCode = 0
			return m, bubbletea.Quit
		case "ctrl+c":
			m.exitCode = 1
			return m, bubbletea.Quit
		case "enter":
			if len(m.entries) > 0 {
				current := m.entries[m.cursor]
				if current.IsDir() {
					newPath := filepath.Join(m.path, current.Name())
					m.path = newPath
					m.cursor = 0
					m.loadEntries()
				}
			}
		case "backspace":
			parent := filepath.Dir(m.path)
			if parent != m.path {
				m.path = parent
				m.cursor = 0
				m.loadEntries()
			}
		case "up", "k":
			if m.cursor > 0 {
				m.cursor--
			}
		case "down", "j":
			if m.cursor < len(m.entries)-1 {
				m.cursor++
			}
		case "home", "shift+up":
			m.cursor = 0
		case "end", "shift+down":
			if len(m.entries) > 0 {
				m.cursor = len(m.entries) - 1
			}
		}
	case bubbletea.WindowSizeMsg:
		// Handle window resize
	}

	return m, nil
}

func (m Model) View() string {
	var s strings.Builder

	// Print current path
	s.WriteString(m.path + "\n")

	// Print entries
	for i, entry := range m.entries {
		if i == m.cursor {
			s.WriteString("> ")
		} else {
			s.WriteString("  ")
		}

		if entry.IsDir() {
			s.WriteString(entry.Name() + "/")
		} else {
			s.WriteString(entry.Name())
		}
		s.WriteString("\n")
	}

	if len(m.entries) == 0 {
		s.WriteString("(no files)\n")
	}

	return s.String()
}
