	Icons      bool
	DirOnly    bool
	HideHidden bool
	Preview    bool
	WithBorder bool
	Fuzzy      bool
	StartPath  string
}

type App struct {
	config       Config
	path         string
	entries      []fs.DirEntry
	cursor       int
	width        int
	height       int
	exitPath     string
	previewOn    bool
	originalTerm syscall.Termios
}

func main() {
	config := parseArgs()

	startPath := config.StartPath
	if startPath == "" {
		var err error
		startPath, err = os.Getwd()
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			os.Exit(1)
		}
	}

	// Open TTY to ensure it's available
	tty, err := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if err != nil {
		fmt.Fprintf(os.Stderr, "panic: could not open a new TTY: %v\n", err)
		os.Exit(2)
	}
	defer tty.Close()

	app := &App{
		config:    config,
		path:      startPath,
		cursor:    0,
		previewOn: config.Preview,
	}

	if err := app.loadEntries(); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}

	// Enable raw mode
	if err := app.enableRaw(); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
	defer app.disableRaw()

	// Run main loop
	app.run()

	if app.exitPath != "" {
		fmt.Println(app.exitPath)
	}
}

func parseArgs() Config {
	config := Config{
		StartPath: ".",
	}

	args := os.Args[1:]
	for i := 0; i < len(args); i++ {
		switch args[i] {
		case "-h", "--help":
			printHelp()
			os.Exit(1)
		case "--version":
			fmt.Println(version)
			os.Exit(0)
		case "--icons":
			config.Icons = true
		case "--dir-only":
			config.DirOnly = true
		case "--hide-hidden":
			config.HideHidden = true
		case "--preview":
			config.Preview = true
		case "--with-border":
			config.WithBorder = true
		case "--fuzzy":
			config.Fuzzy = true
		default:
			if !strings.HasPrefix(args[i], "-") {
				config.StartPath = args[i]
			}
		}
	}

	return config
}

func printHelp() {
	fmt.Printf(`
  walk %s

  Usage: walk [path]

    arrows, hjkl  Move cursor
    enter         Enter directory
    backspace     Exit directory
    space         Toggle preview
    esc, q        Exit with cd
    ctrl+c        Exit without cd
    /             Fuzzy search
    d, delete     Delete file or dir
    y             Copy to clipboard
    .             Hide hidden files
    ?             Show help

  Flags:

    --icons        display icons
    --dir-only     show dirs only
    --hide-hidden  hide hidden files
    --preview      display preview
    --with-border  preview with border
    --fuzzy        fuzzy mode

`, version)
}

func (app *App) loadEntries() error {
	entries, err := os.ReadDir(app.path)
	if err != nil {
		return err
	}

	// Filter entries
	filtered := []fs.DirEntry{}
	for _, e := range entries {
		if app.config.HideHidden && strings.HasPrefix(e.Name(), ".") {
			continue
		}
		if app.config.DirOnly && !e.IsDir() {
			continue
		}
		filtered = append(filtered, e)
	}

	// Sort entries - directories first, then alphabetically
	sort.Slice(filtered, func(i, j int) bool {
		iIsDir := filtered[i].IsDir()
		jIsDir := filtered[j].IsDir()
		if iIsDir != jIsDir {
			return iIsDir
		}
		return filtered[i].Name() < filtered[j].Name()
	})

	app.entries = filtered
	if app.cursor >= len(app.entries) {
		app.cursor = 0
	}

	return nil
