	if _, _, err := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), uintptr(syscall.TCSETS), uintptr(unsafe.Pointer(&newTerm))); err != 0 {
		return fmt.Errorf("TCSETS failed: %w", err)
	}

