			}
		} else {
			if i == app.cursor {
				fmt.Printf("\033[1m%s\033[0m\n", entry.Name())
			} else {
				fmt.Printf(" %s\n", entry.Name())
			}
		}
	}

	if len(app.entries) == 0 {
		fmt.Println("No files")
	}
